.darma-loader-darma-b14-blender-blades { --accent: var(--loader-color, #84cc16); --accent-2: var(--loader-secondary-color, #e2e8f0); width: var(--loader-size, 104px); height: var(--loader-size, 104px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b14-blender-blades::before { content: ''; position: absolute; z-index: 2; top: 4%; left: 20%; width: 60%; height: 9%; border-radius: 4px; background: linear-gradient(color-mix(in srgb, #fff 18%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b14-blender-blades .darma-loader-darma-b14-blender-blades__jug { position: relative; width: 62%; height: 78%; margin-top: 8%; overflow: hidden; border-radius: 7% 7% 20% 20%; background: linear-gradient(102deg, rgba(255, 255, 255, .5), color-mix(in srgb, #fff 34%, var(--accent-2))); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 18%, var(--accent-2)); }
.darma-loader-darma-b14-blender-blades .darma-loader-darma-b14-blender-blades__jug::after { content: ''; position: absolute; bottom: -30%; left: -12%; width: 124%; height: 92%; border-radius: 50%; background: conic-gradient(from 0deg, var(--accent) 0 22%, color-mix(in srgb, #fff 34%, var(--accent)) 22% 44%, var(--accent) 44% 66%, color-mix(in srgb, #fff 34%, var(--accent)) 66% 88%, var(--accent) 88% 100%); animation: darma-loader-darma-b14-blender-blades-vortex calc(var(--loader-speed, 1s) * .7) linear infinite; }
.darma-loader-darma-b14-blender-blades .darma-loader-darma-b14-blender-blades__jug span { position: absolute; z-index: 2; bottom: 16%; left: 50%; width: 44%; height: 6%; margin-left: -22%; border-radius: 2px; background: linear-gradient(90deg, #64748b, #f1f5f9, #64748b); animation: darma-loader-darma-b14-blender-blades-blade calc(var(--loader-speed, 1s) * .35) linear infinite; }
.darma-loader-darma-b14-blender-blades .darma-loader-darma-b14-blender-blades__jug span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -.0875); }
@keyframes darma-loader-darma-b14-blender-blades-vortex { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b14-blender-blades-blade { 0% { transform: rotate(0deg) scaleX(1); } 50% { transform: rotate(180deg) scaleX(.24); } 100% { transform: rotate(360deg) scaleX(1); } }

